import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BYgiQ6KE.js";const c=JSON.parse('{"title":"六阶段学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1793863170000}'),i={name:"guide/index.md"};function o(l,t,n,s,u,g){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="六阶段学习路线" tabindex="-1">六阶段学习路线 <a class="header-anchor" href="#六阶段学习路线" aria-label="Permalink to &quot;六阶段学习路线&quot;">​</a></h1><p>这套教程假设你会 JavaScript / TypeScript，但不要求事先接触过 Angular。每一章都遵循同一结构：<strong>学习目标 → 概念讲解 → 可运行示例 → 常见坑 → 练习 → 自测</strong>。</p><p>示例不是截图或伪代码，而是 <code>examples/</code> 下的真实 Angular 22 工程。页面中的 Playground 会在浏览器里启动完整开发服务器，你可以直接改代码并看到结果。</p><h2 id="路线总览" tabindex="-1">路线总览 <a class="header-anchor" href="#路线总览" aria-label="Permalink to &quot;路线总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>关键词</th><th>章节</th><th>学完能做什么</th></tr></thead><tbody><tr><td>第一篇 · 入门</td><td>组件、模板、绑定</td><td><a href="/angular-tutorial-site/guide/part1/01-first-app">01 环境搭建</a>、<a href="/angular-tutorial-site/guide/part1/02-template-syntax">02 模板语法</a></td><td>独立写出一个可交互的 Angular 页面</td></tr><tr><td>第二篇 · 基础</td><td>DI、路由、表单</td><td><a href="/angular-tutorial-site/guide/part2/03-di-service">03 依赖注入</a>、<a href="/angular-tutorial-site/guide/part2/04-routing-form">04 路由与表单</a></td><td>搭出多页面应用并完成表单校验</td></tr><tr><td>第三篇 · 进阶</td><td>Signals、RxJS</td><td><a href="/angular-tutorial-site/guide/part3/05-signals">05 Signals</a>、<a href="/angular-tutorial-site/guide/part3/06-http-rxjs">06 HTTP 数据流</a></td><td>用响应式方式管理状态与异步数据</td></tr><tr><td>第四篇 · 工程化</td><td>构建、测试</td><td><a href="/angular-tutorial-site/guide/part4/07-build">07 构建优化</a>、<a href="/angular-tutorial-site/guide/part4/08-testing">08 测试门禁</a></td><td>控制包体积并建立可回归的质量基线</td></tr><tr><td>第五篇 · 深度</td><td>性能、可访问性</td><td><a href="/angular-tutorial-site/guide/part5/09-performance">09 性能调优</a>、<a href="/angular-tutorial-site/guide/part5/10-a11y-i18n">10 无障碍与国际化</a></td><td>让大型列表流畅、界面可被所有人使用</td></tr><tr><td>第六篇 · 精通</td><td>架构、原理</td><td><a href="/angular-tutorial-site/guide/part6/11-architecture">11 分层架构</a>、<a href="/angular-tutorial-site/guide/part6/12-internals">12 框架原理</a></td><td>设计可演进的大型应用并解释框架行为</td></tr><tr><td>第七篇 · 精通专题</td><td>路由/表单/安全/SSR/编译器/治理</td><td><a href="/angular-tutorial-site/guide/part7/13-routing-advanced">13 路由进阶</a>、<a href="/angular-tutorial-site/guide/part7/14-forms-advanced">14 表单进阶</a>、<a href="/angular-tutorial-site/guide/part7/15-security">15 安全边界</a>、<a href="/angular-tutorial-site/guide/part7/16-ssr-hydration">16 SSR 与水合</a>、<a href="/angular-tutorial-site/guide/part7/17-compiler-ivy">17 编译器与 Ivy</a>、<a href="/angular-tutorial-site/guide/part7/18-migration-governance">18 迁移与治理</a></td><td>处理复杂导航、复杂表单、不可信内容、服务端渲染与长期演进</td></tr></tbody></table><h2 id="建议的学习方式" tabindex="-1">建议的学习方式 <a class="header-anchor" href="#建议的学习方式" aria-label="Permalink to &quot;建议的学习方式&quot;">​</a></h2><ol><li><strong>先跑再读</strong>：打开章节里的 Playground，点击「立即加载」在页面内编辑运行，或在新窗口打开沙箱。</li><li><strong>每章至少改一次代码</strong>：把示例中的参数、条件或数据结构改掉，观察视图如何变化。</li><li><strong>先做练习再看自测</strong>：自测题用于检查理解，不替代动手。</li><li><strong>按阶段提交</strong>：每完成一篇，把练习代码整理成自己的小项目，而不是只收藏文档。</li></ol><h2 id="版本基线" tabindex="-1">版本基线 <a class="header-anchor" href="#版本基线" aria-label="Permalink to &quot;版本基线&quot;">​</a></h2><ul><li>Angular <strong>22.2.3</strong>，standalone 组件为默认形态</li><li>TypeScript <strong>6.0.x</strong></li><li>Node.js <strong>22.13+</strong>（CI 使用 Node 24）</li><li>包管理器 <strong>pnpm 12</strong></li><li>文档框架 <strong>VitePress 1.6.4</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">关于 zoneless</p><p>Angular 22 默认使用 zoneless 变更检测。教程会明确区分「signal 驱动」「事件驱动」与「手动变更检测」三种刷新路径，避免把旧版 Zone.js 的经验直接套用。</p></div><h2 id="代码与站点如何同步" tabindex="-1">代码与站点如何同步 <a class="header-anchor" href="#代码与站点如何同步" aria-label="Permalink to &quot;代码与站点如何同步&quot;">​</a></h2><p><code>examples/&lt;id&gt;/</code> 是示例的唯一真源。构建前运行 <code>pnpm sync:examples</code>，把源码汇总为 <code>docs/.vitepress/generated/examples.json</code>；<code>pnpm sync:sandboxes</code> 再把示例发布为 CodeSandbox 在线沙箱，Playground 组件按 id 加载对应的沙箱。</p><p>因此：<strong>改示例只改 <code>examples/</code>，不要直接改生成物</strong>。CI 会校验生成物与源码一致，并检查每个 <code>&lt;Playground&gt;</code> 引用的示例是否存在。</p>',13)])])}const h=a(i,[["render",o]]);export{c as __pageData,h as default};
